-- Dori Bank loan system: secured RPC-only loan workflow.
create table if not exists public.dori_bank_loan_products(id text primary key,name text not null,term_days integer not null check(term_days between 7 and 365),annual_rate_pct numeric(5,2) not null check(annual_rate_pct between 8 and 30),min_amount bigint not null check(min_amount>0),max_amount bigint not null check(max_amount>=min_amount),description text not null default '',is_active boolean not null default true,updated_at timestamptz not null default clock_timestamp());
create table if not exists public.dori_bank_loans(id uuid primary key default gen_random_uuid(),auth_user_id uuid not null references auth.users(id),account_number text not null references public.dori_bank_accounts(account_number),product_id text not null references public.dori_bank_loan_products(id),product_name text not null,principal bigint not null check(principal>0),annual_rate_pct numeric(5,2) not null check(annual_rate_pct>=8),term_days integer not null check(term_days between 7 and 365),interest_amount bigint not null check(interest_amount>=0),total_due bigint not null check(total_due>=principal),repaid_amount bigint not null default 0 check(repaid_amount>=0),purpose text not null default '',status text not null default 'pending' check(status in('pending','active','paid','rejected','overdue')),created_at timestamptz not null default clock_timestamp(),reviewed_at timestamptz,reviewed_by uuid,due_at timestamptz,settled_at timestamptz);
create index if not exists dori_bank_loans_user_created_idx on public.dori_bank_loans(auth_user_id,created_at desc);
create index if not exists dori_bank_loans_status_created_idx on public.dori_bank_loans(status,created_at);
alter table public.dori_bank_loan_products enable row level security;alter table public.dori_bank_loans enable row level security;
revoke all on public.dori_bank_loan_products,public.dori_bank_loans from anon,authenticated;
insert into public.dori_bank_loan_products(id,name,term_days,annual_rate_pct,min_amount,max_amount,description,is_active) values
('small_personal','돌이 생활안정 대출',30,8.50,10000,1000000,'짧은 기간 동안 필요한 자금을 마련하는 기본 대출입니다. 연 8.50% 단리 기준.',true),
('standard_personal','돌이 플러스 신용대출',90,11.00,50000,10000000,'중간 기간 자금에 적합한 일반 신용대출입니다. 연 11.00% 단리 기준.',true),
('long_term_personal','돌이 장기 안심대출',180,15.00,100000,50000000,'상환 기간이 긴 대신 금리가 높은 장기 대출입니다. 연 15.00% 단리 기준.',true) on conflict(id) do nothing;
create or replace function public.dori_bank_loans_dashboard() returns jsonb language plpgsql security definer set search_path='' as $function$
declare v_auth uuid:=auth.uid();v_account public.dori_bank_accounts%rowtype;v_uid text;v_balance bigint;v_products jsonb;v_loans jsonb;
begin
if v_auth is null then raise exception '로그인 후 이용해 주세요.' using errcode='28000';end if;perform public.dori_bank_ensure_account();select * into v_account from public.dori_bank_accounts where auth_user_id=v_auth and status='active';if not found then raise exception '계좌를 사용할 수 없습니다.' using errcode='42501';end if;
select site_user_id into v_uid from public.dori_bank_identity_map where auth_user_id=v_auth;select coalesce(doldolcoin,0) into v_balance from public.users where user_id=v_uid;
select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'term_days',term_days,'annual_rate_pct',annual_rate_pct::text,'min_amount',min_amount::text,'max_amount',max_amount::text,'description',description) order by term_days),'[]'::jsonb) into v_products from public.dori_bank_loan_products where is_active;
update public.dori_bank_loans set status='overdue' where auth_user_id=v_auth and status='active' and due_at<clock_timestamp() and repaid_amount<total_due;
select coalesce(jsonb_agg(jsonb_build_object('id',id::text,'product_id',product_id,'product_name',product_name,'principal',principal::text,'annual_rate_pct',annual_rate_pct::text,'term_days',term_days,'interest_amount',interest_amount::text,'total_due',total_due::text,'repaid_amount',repaid_amount::text,'remaining_due',(total_due-repaid_amount)::text,'purpose',purpose,'status',status,'created_at',created_at,'due_at',due_at,'reviewed_at',reviewed_at) order by created_at desc),'[]'::jsonb) into v_loans from public.dori_bank_loans where auth_user_id=v_auth;
return jsonb_build_object('balance',v_balance::text,'products',v_products,'loans',v_loans);end;$function$;
create or replace function public.dori_bank_request_loan(p_product_id text,p_amount numeric,p_purpose text default '') returns jsonb language plpgsql security definer set search_path='' as $function$
declare v_auth uuid:=auth.uid();v_account public.dori_bank_accounts%rowtype;v_product public.dori_bank_loan_products%rowtype;v_loan public.dori_bank_loans%rowtype;v_amount bigint;v_interest numeric;v_purpose text:=left(trim(coalesce(p_purpose,'')),160);
begin
if v_auth is null then raise exception '로그인 후 이용해 주세요.' using errcode='28000';end if;if p_amount is null or p_amount<=0 or p_amount<>trunc(p_amount) or p_amount>9223372036854775807::numeric then raise exception '대출 신청 금액은 1 이상의 정수여야 합니다.' using errcode='22023';end if;v_amount:=p_amount::bigint;if length(v_purpose)<3 then raise exception '대출 목적을 3자 이상 입력해 주세요.' using errcode='22023';end if;perform public.dori_bank_ensure_account();select * into v_account from public.dori_bank_accounts where auth_user_id=v_auth and status='active';if not found then raise exception '계좌를 사용할 수 없습니다.' using errcode='42501';end if;
if exists(select 1 from public.dori_bank_loans where auth_user_id=v_auth and status in('pending','active','overdue')) then raise exception '심사 중이거나 상환 중인 대출이 있습니다. 기존 대출을 먼저 정리해 주세요.' using errcode='22023';end if;select * into v_product from public.dori_bank_loan_products where id=p_product_id and is_active;if not found then raise exception '현재 신청할 수 없는 대출 상품입니다.' using errcode='P0002';end if;if v_amount<v_product.min_amount or v_amount>v_product.max_amount then raise exception '신청 금액이 상품의 한도를 벗어났습니다.' using errcode='22023';end if;
v_interest:=floor(v_amount::numeric*v_product.annual_rate_pct/100*v_product.term_days/365);if v_interest+v_amount>9223372036854775807::numeric then raise exception '상환 예정액이 시스템 한도를 초과합니다.' using errcode='22003';end if;
insert into public.dori_bank_loans(auth_user_id,account_number,product_id,product_name,principal,annual_rate_pct,term_days,interest_amount,total_due,purpose) values(v_auth,v_account.account_number,v_product.id,v_product.name,v_amount,v_product.annual_rate_pct,v_product.term_days,v_interest::bigint,(v_amount+v_interest)::bigint,v_purpose) returning * into v_loan;
insert into public.dori_bank_audit_logs(actor_user_id,action,target_type,target_id,details) values(v_auth,'loan_requested','loan',v_loan.id::text,jsonb_build_object('amount',v_amount::text,'product_id',v_product.id,'rate',v_product.annual_rate_pct::text));return jsonb_build_object('ok',true,'loan_id',v_loan.id::text,'status',v_loan.status,'principal',v_loan.principal::text,'interest_amount',v_loan.interest_amount::text,'total_due',v_loan.total_due::text);end;$function$;
create or replace function public.dori_bank_repay_loan(p_loan_id uuid,p_amount numeric) returns jsonb language plpgsql security definer set search_path='' as $function$
declare v_auth uuid:=auth.uid();v_loan public.dori_bank_loans%rowtype;v_account public.dori_bank_accounts%rowtype;v_uid text;v_balance bigint;v_amount bigint;v_new_balance bigint;v_repaid bigint;v_status text;
begin
if v_auth is null then raise exception '로그인 후 이용해 주세요.' using errcode='28000';end if;if p_amount is null or p_amount<=0 or p_amount<>trunc(p_amount) or p_amount>9223372036854775807::numeric then raise exception '상환 금액은 1 이상의 정수여야 합니다.' using errcode='22023';end if;v_amount:=p_amount::bigint;perform public.dori_bank_ensure_account();select * into v_loan from public.dori_bank_loans where id=p_loan_id and auth_user_id=v_auth for update;if not found then raise exception '대출 정보를 찾을 수 없습니다.' using errcode='P0002';end if;if v_loan.status not in('active','overdue') then raise exception '현재 상환할 수 있는 대출이 아닙니다.' using errcode='22023';end if;if v_amount>v_loan.total_due-v_loan.repaid_amount then raise exception '남은 상환 예정액보다 큰 금액은 입력할 수 없습니다.' using errcode='22023';end if;
select * into v_account from public.dori_bank_accounts where auth_user_id=v_auth and status='active';select site_user_id into v_uid from public.dori_bank_identity_map where auth_user_id=v_auth;perform 1 from public.users where user_id=v_uid for update;select coalesce(doldolcoin,0) into v_balance from public.users where user_id=v_uid;if v_balance<v_amount then raise exception '지갑의 사용 가능 돌돌코인이 부족합니다.' using errcode='22023';end if;update public.users set doldolcoin=doldolcoin-v_amount where user_id=v_uid returning doldolcoin into v_new_balance;
v_repaid:=v_loan.repaid_amount+v_amount;v_status:=case when v_repaid>=v_loan.total_due then 'paid' when v_loan.due_at<clock_timestamp() then 'overdue' else 'active' end;update public.dori_bank_loans set repaid_amount=v_repaid,status=v_status,settled_at=case when v_status='paid' then clock_timestamp() else settled_at end where id=v_loan.id;
insert into public.dori_bank_transactions(account_number,tx_type,direction,amount,balance_after,counterparty_name,description) values(v_account.account_number,'loan_repayment','debit',v_amount,v_new_balance,'돌이 은행 대출',v_loan.product_name||' 상환');insert into public.dori_bank_audit_logs(actor_user_id,action,target_type,target_id,details) values(v_auth,'loan_repaid','loan',v_loan.id::text,jsonb_build_object('amount',v_amount::text,'remaining',(v_loan.total_due-v_repaid)::text,'status',v_status));return jsonb_build_object('ok',true,'repaid',v_amount::text,'remaining_due',(v_loan.total_due-v_repaid)::text,'balance',v_new_balance::text,'status',v_status);end;$function$;
create or replace function public.dori_bank_admin_loan_applications() returns jsonb language plpgsql security definer set search_path='' as $function$
declare v_rows jsonb;begin if not public.admin_is_authorized() then raise exception '은행 운영 권한이 없습니다.' using errcode='42501';end if;select coalesce(jsonb_agg(jsonb_build_object('id',l.id::text,'account_number',l.account_number,'product_name',l.product_name,'principal',l.principal::text,'annual_rate_pct',l.annual_rate_pct::text,'term_days',l.term_days,'interest_amount',l.interest_amount::text,'total_due',l.total_due::text,'purpose',l.purpose,'status',l.status,'created_at',l.created_at,'due_at',l.due_at,'repaid_amount',l.repaid_amount::text,'remaining_due',(l.total_due-l.repaid_amount)::text,'account_owner',u.name) order by l.created_at desc),'[]'::jsonb) into v_rows from public.dori_bank_loans l left join public.dori_bank_accounts a on a.account_number=l.account_number left join public.users u on u.user_id=a.site_user_id;return v_rows;end;$function$;
create or replace function public.dori_bank_admin_review_loan(p_loan_id uuid,p_approve boolean) returns jsonb language plpgsql security definer set search_path='' as $function$
declare v_loan public.dori_bank_loans%rowtype;v_account public.dori_bank_accounts%rowtype;v_uid text;v_balance bigint;v_new_balance bigint;
begin if not public.admin_is_authorized() then raise exception '은행 운영 권한이 없습니다.' using errcode='42501';end if;select * into v_loan from public.dori_bank_loans where id=p_loan_id for update;if not found then raise exception '대출 신청을 찾을 수 없습니다.' using errcode='P0002';end if;if v_loan.status<>'pending' then raise exception '이미 심사 처리된 신청입니다.' using errcode='22023';end if;
if not p_approve then update public.dori_bank_loans set status='rejected',reviewed_at=clock_timestamp(),reviewed_by=auth.uid() where id=v_loan.id;insert into public.dori_bank_audit_logs(actor_user_id,action,target_type,target_id,details) values(auth.uid(),'loan_rejected','loan',v_loan.id::text,'{}'::jsonb);return jsonb_build_object('ok',true,'status','rejected');end if;
select * into v_account from public.dori_bank_accounts where auth_user_id=v_loan.auth_user_id and status='active' for update;if not found then raise exception '신청자의 계좌를 사용할 수 없습니다.' using errcode='42501';end if;select site_user_id into v_uid from public.dori_bank_identity_map where auth_user_id=v_loan.auth_user_id;perform 1 from public.users where user_id=v_uid for update;select coalesce(doldolcoin,0) into v_balance from public.users where user_id=v_uid;if v_balance::numeric+v_loan.principal>9223372036854775807::numeric then raise exception '대출금 지급 후 지갑 잔액 한도를 초과합니다.' using errcode='22003';end if;update public.users set doldolcoin=doldolcoin+v_loan.principal where user_id=v_uid returning doldolcoin into v_new_balance;update public.dori_bank_loans set status='active',reviewed_at=clock_timestamp(),reviewed_by=auth.uid(),due_at=clock_timestamp()+make_interval(days=>term_days) where id=v_loan.id;
insert into public.dori_bank_transactions(account_number,tx_type,direction,amount,balance_after,counterparty_name,description) values(v_account.account_number,'loan_disbursement','credit',v_loan.principal,v_new_balance,'돌이 은행 대출',v_loan.product_name||' 대출금 지급');insert into public.dori_bank_audit_logs(actor_user_id,action,target_type,target_id,details) values(auth.uid(),'loan_approved','loan',v_loan.id::text,jsonb_build_object('principal',v_loan.principal::text,'total_due',v_loan.total_due::text));return jsonb_build_object('ok',true,'status','active','principal',v_loan.principal::text,'total_due',v_loan.total_due::text,'balance',v_new_balance::text);end;$function$;
revoke all on function public.dori_bank_loans_dashboard() from public,anon;revoke all on function public.dori_bank_request_loan(text,numeric,text) from public,anon;revoke all on function public.dori_bank_repay_loan(uuid,numeric) from public,anon;revoke all on function public.dori_bank_admin_loan_applications() from public,anon,authenticated;revoke all on function public.dori_bank_admin_review_loan(uuid,boolean) from public,anon;grant execute on function public.dori_bank_loans_dashboard() to authenticated;grant execute on function public.dori_bank_request_loan(text,numeric,text) to authenticated;grant execute on function public.dori_bank_repay_loan(uuid,numeric) to authenticated;grant execute on function public.dori_bank_admin_loan_applications() to authenticated;grant execute on function public.dori_bank_admin_review_loan(uuid,boolean) to authenticated;